loadTop321:
async function loadTop321(force=false){
 const h=host();if(!h)return false;const token=++topToken;loading321('Carregando Top 10…');
 h.innerHTML='<section class="ct288-top-shell"><div class="ct288-top-title"><h2>Top 10</h2></div><div class="ct288-provider-row" data-ct321-providers><div class="ct263-loading">Carregando streamings…</div></div><div data-ct321-top-content><div class="ct263-loading">Montando Top 10…</div></div></section>';
 try{
  const providers=rows(typeof ct171Providers==='function'?await ct171Providers():[]);
  if(token!==topToken||String(discover?.tab)!=='top10')return false;
  if(!force||!state.topProvider||!providers.some(p=>Number(p.provider_id)===Number(state.topProvider)))state.topProvider=Number(providers[0]?.provider_id||0);
  try{ct171TopProvider=state.topProvider}catch{}
  const box=q('[data-ct321-providers]');
  if(box)box.innerHTML=providers.map(p=>'<button type="button" class="ct288-provider '+(Number(p.provider_id)===Number(state.topProvider)?'active':'')+'" data-ct321-provider="'+Number(p.provider_id)+'">'+(p.logo_path?'<span style="background-image:url(\''+img(p.logo_path,'w92')+'\')"></span>':'')+'<b>'+esc(p.provider_name||'Streaming')+'</b></button>').join('')||'<div class="empty">Nenhum streaming disponível.</div>';
  if(state.topProvider)return paintTop321(state.topProvider,token,force);
  loaded321();return false;
 }catch(e){
  const c=q('[data-ct321-top-content]');if(c)c.innerHTML='<div class="empty">Não foi possível carregar os streamings agora.<br><button class="chip" type="button" data-ct321-retry>Tentar novamente</button></div>';loaded321();return false;
 }
}
